import{_ as t,a,c as s,ac as o}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第一册：英语初阶 · 单元 6 复习与自测 · 第121–127课","description":"L121–L144 原创练习和答案解析。","frontmatter":{"title":"第一册：英语初阶 · 单元 6 复习与自测 · 第121–127课","description":"L121–L144 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-1/unit-06/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 单元 6 复习与自测","summary":"L121–L144 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 单元 6 复习与自测","link":"/life/english/new-concept/book-1/unit-06/review"},"next":{"text":"第一册：英语初阶 · 单元 6 复习与自测 · 第128–134课","link":"/life/english/new-concept/book-1/unit-06/review-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 单元 6 复习与自测","link":"/life/english/new-concept/book-1/unit-06/review"},"next":{"text":"第一册：英语初阶 · 单元 6 复习与自测 · 第128–134课","link":"/life/english/new-concept/book-1/unit-06/review-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-06/review-part-01.md","filePath":"life/english/new-concept/book-1/unit-06/review-part-01.md"}'),n={name:"life/english/new-concept/book-1/unit-06/review-part-01.md"};function i(r,e,h,l,p,d){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-单元-6-复习与自测-·-第121–127课" tabindex="-1">第一册：英语初阶 · 单元 6 复习与自测 · 第121–127课 <a class="header-anchor" href="#第一册-英语初阶-·-单元-6-复习与自测-·-第121–127课" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 6 复习与自测 · 第121–127课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/unit-06/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/unit-06/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-06/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-06/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-06/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="第一册-英语初阶-·-单元-6-复习与自测" tabindex="-1">第一册：英语初阶 · 单元 6 复习与自测 <a class="header-anchor" href="#第一册-英语初阶-·-单元-6-复习与自测" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 6 复习与自测 {#第一册-英语初阶-·-单元-6-复习与自测}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-1/unit-06/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-06/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-06/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-06/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-121-·-关系代词作主语" tabindex="-1">Lesson 121 · 关系代词作主语 <a class="header-anchor" href="#lesson-121-·-关系代词作主语" aria-label="Permalink to &quot;Lesson 121 · 关系代词作主语 {#lesson-121-·-关系代词作主语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The woman who lives upstairs is a violinist.</p><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1 {#练习-1}&quot;">​</a></h3><p>填关系代词（指人作主语）：The woman ___ lives upstairs.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> who（限制性从句也可用 that）</p><p><strong>解析：</strong> 按本课规则判断：定语从句用来修饰前面的名词。指人可用 who，指物可用 which，限制性从句中常可用 that。关系代词在从句中作主语时不能省略，也不能再重复 he/it 等主语。先找先行词，再确定从句缺什么成分，不能只看到中文“的”就机械插入 who。介词短语 in a hat 也可直接修饰人。</p></details><p><strong>表达迁移：</strong> 围绕“通过补充信息识别人或物”写两至三句，再读给同伴听。至少使用一次关系代词作主语，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The woman who lives upstairs is a violinist. The lamp that stands by the sofa is broken.</p><p>The woman 是先行词，who 在从句中作 lives 的主语，不能省略；主句谓语为 is。 The lamp 是先行词，that 作 stands 的主语；by the sofa 是从句内位置说明，主句 is broken 说明状态。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-121">回看本课</a></p><h2 id="lesson-122-·-关系代词作主语" tabindex="-1">Lesson 122 · 关系代词作主语 <a class="header-anchor" href="#lesson-122-·-关系代词作主语" aria-label="Permalink to &quot;Lesson 122 · 关系代词作主语 {#lesson-122-·-关系代词作主语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The lamp that stands by the sofa is broken.</p><h3 id="练习-1-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-1" aria-label="Permalink to &quot;练习 1 {#练习-1-1}&quot;">​</a></h3><p>删去重复成分：the lamp that it stands by the sofa.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the lamp that stands by the sofa</p><p><strong>解析：</strong> 按本课规则判断：定语从句用来修饰前面的名词。指人可用 who，指物可用 which，限制性从句中常可用 that。关系代词在从句中作主语时不能省略，也不能再重复 he/it 等主语。先找先行词，再确定从句缺什么成分，不能只看到中文“的”就机械插入 who。介词短语 in a hat 也可直接修饰人。</p></details><p><strong>表达迁移：</strong> 围绕“通过补充信息识别人或物”写两至三句，再读给同伴听。至少使用一次关系代词作主语，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The lamp that stands by the sofa is broken. The woman who lives upstairs is a violinist.</p><p>The lamp 是先行词，that 作 stands 的主语；by the sofa 是从句内位置说明，主句 is broken 说明状态。 The woman 是先行词，who 在从句中作 lives 的主语，不能省略；主句谓语为 is。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-122">回看本课</a></p><h2 id="lesson-123-·-关系代词作宾语" tabindex="-1">Lesson 123 · 关系代词作宾语 <a class="header-anchor" href="#lesson-123-·-关系代词作宾语" aria-label="Permalink to &quot;Lesson 123 · 关系代词作宾语 {#lesson-123-·-关系代词作宾语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The guide we met in Perth spoke three languages.</p><h3 id="练习-1-2" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-2" aria-label="Permalink to &quot;练习 1 {#练习-1-2}&quot;">​</a></h3><p>在 the guide that we met 中，that 能省略吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 能；that 在限制性定语从句中作 met 的宾语。</p><p><strong>解析：</strong> 按本课规则判断：在限制性定语从句中，关系代词若作宾语，常可省略，如 the place we visited。指人正式文体可用 whom，口语中 who 或省略更常见。省略的前提是从句已有主语而缺宾语；关系代词作主语时不能随便省略。visit 是及物动词，visit the city 不需额外加 to，但 go to the city 需要 to。</p></details><p><strong>表达迁移：</strong> 围绕“讲述旅行中见到的人与事物”写两至三句，再读给同伴听。至少使用一次关系代词作宾语，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The guide we met in Perth spoke three languages. This is the photograph that I took at the harbour.</p><p>The guide 是先行词；we met 中 we 为主语，被省略的关系代词是 met 的宾语；spoke 是主句谓语。 That 在从句 I took 中作宾语，可在这一限制性从句中省略；at the harbour 表拍照地点。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-123">回看本课</a></p><h2 id="lesson-124-·-关系代词作宾语" tabindex="-1">Lesson 124 · 关系代词作宾语 <a class="header-anchor" href="#lesson-124-·-关系代词作宾语" aria-label="Permalink to &quot;Lesson 124 · 关系代词作宾语 {#lesson-124-·-关系代词作宾语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> This is the photograph that I took at the harbour.</p><h3 id="练习-1-3" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-3" aria-label="Permalink to &quot;练习 1 {#练习-1-3}&quot;">​</a></h3><p>改正：the photograph that I took it.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the photograph that I took</p><p><strong>解析：</strong> 按本课规则判断：在限制性定语从句中，关系代词若作宾语，常可省略，如 the place we visited。指人正式文体可用 whom，口语中 who 或省略更常见。省略的前提是从句已有主语而缺宾语；关系代词作主语时不能随便省略。visit 是及物动词，visit the city 不需额外加 to，但 go to the city 需要 to。</p></details><p><strong>表达迁移：</strong> 围绕“讲述旅行中见到的人与事物”写两至三句，再读给同伴听。至少使用一次关系代词作宾语，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>This is the photograph that I took at the harbour. The guide we met in Perth spoke three languages.</p><p>That 在从句 I took 中作宾语，可在这一限制性从句中省略；at the harbour 表拍照地点。 The guide 是先行词；we met 中 we 为主语，被省略的关系代词是 met 的宾语；spoke 是主句谓语。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-124">回看本课</a></p><h2 id="lesson-125-·-have-to-的时态与否定" tabindex="-1">Lesson 125 · have to 的时态与否定 <a class="header-anchor" href="#lesson-125-·-have-to-的时态与否定" aria-label="Permalink to &quot;Lesson 125 · have to 的时态与否定 {#lesson-125-·-have-to-的时态与否定}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I had to water the plants before work.</p><h3 id="练习-1-4" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-4" aria-label="Permalink to &quot;练习 1 {#练习-1-4}&quot;">​</a></h3><p>填过去形式：Yesterday I ___ to water the plants.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> had</p><p><strong>解析：</strong> 按本课规则判断：have to 常表示客观要求，第三人称为 has to，过去为 had to，未来可用 will have to。疑问和否定借助 do/does/did：Does she have to ...?、She doesn&#39;t have to ...。must 没有普通过去式，过去的义务常用 had to。don&#39;t need to 与 don&#39;t have to 都能表示不必，不能误读为禁止。</p></details><p><strong>表达迁移：</strong> 围绕“说明不得不做与不需要做”写两至三句，再读给同伴听。至少使用一次have to 的时态与否定，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I had to water the plants before work. She does not have to work this Sunday.</p><p>Had to 是过去的客观必要，后接原形 water；plants 是宾语，before work 表发生时间。 Does not have to 表第三人称单数的“不必”；have 恢复原形，this Sunday 指本次星期日。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-125">回看本课</a></p><h2 id="lesson-126-·-have-to-的时态与否定" tabindex="-1">Lesson 126 · have to 的时态与否定 <a class="header-anchor" href="#lesson-126-·-have-to-的时态与否定" aria-label="Permalink to &quot;Lesson 126 · have to 的时态与否定 {#lesson-126-·-have-to-的时态与否定}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> She does not have to work this Sunday.</p><h3 id="练习-1-5" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-5" aria-label="Permalink to &quot;练习 1 {#练习-1-5}&quot;">​</a></h3><p>填 have/has：She does not ___ to work.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> 按本课规则判断：have to 常表示客观要求，第三人称为 has to，过去为 had to，未来可用 will have to。疑问和否定借助 do/does/did：Does she have to ...?、She doesn&#39;t have to ...。must 没有普通过去式，过去的义务常用 had to。don&#39;t need to 与 don&#39;t have to 都能表示不必，不能误读为禁止。</p></details><p><strong>表达迁移：</strong> 围绕“说明不得不做与不需要做”写两至三句，再读给同伴听。至少使用一次have to 的时态与否定，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>She does not have to work this Sunday. I had to water the plants before work.</p><p>Does not have to 表第三人称单数的“不必”；have 恢复原形，this Sunday 指本次星期日。 Had to 是过去的客观必要，后接原形 water；plants 是宾语，before work 表发生时间。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-126">回看本课</a></p><h2 id="lesson-127-·-must-cannot-表现在推断" tabindex="-1">Lesson 127 · must/cannot 表现在推断 <a class="header-anchor" href="#lesson-127-·-must-cannot-表现在推断" aria-label="Permalink to &quot;Lesson 127 · must/cannot 表现在推断 {#lesson-127-·-must-cannot-表现在推断}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The office lights are on; someone must be inside.</p><h3 id="练习-1-6" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-6" aria-label="Permalink to &quot;练习 1 {#练习-1-6}&quot;">​</a></h3><p>表达强推断：Someone ___ be inside.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> must</p><p><strong>解析：</strong> 按本课规则判断：must be 在推断中表示根据证据很有把握，不能译为命令意义的“必须是”。can&#39;t be 表根据证据认为不可能；may/might be 表不确定的可能。推断应说明证据，不能把 must 当成证明。情态动词后用原形 be，即便主语是 he/she 也不改为 is。</p></details><p><strong>表达迁移：</strong> 围绕“根据线索推测身份或当前状态”写两至三句，再读给同伴听。至少使用一次must/cannot 表现在推断，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The office lights are on; someone must be inside. That cannot be our bus; it has a different number.</p><p>前半句灯亮着是观察线索；后半句 must be 是强推断，someone 是主语，inside 为地点表语。 Cannot be 表不可能是；分号后 different number 提供推断依据，its number 与 expected bus number 不同。</p></details><p><a href="/life/english/new-concept/book-1/unit-06/lesson-127">回看本课</a></p>',63)])])}const u=t(n,[["render",i]]);export{m as __pageData,u as default};
